#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: 本機查 production 用的唯讀 Cloudflare token（ADR 0011）。
#
#   bash scripts/cloudflare-readonly-wizard.sh      （Windows 用 Git Bash；需要 curl、node、op，以及 npm ci 裝好的套件）
#
# token 只放在 1Password；ENV_FILE 只放 op:// 參照與 Account ID，npm run prod:connect 用它啟動唯讀 proxy。
# 這份跟 ~/.config/naruhodo/op.env 分開：worker:dev、smoke 不會拿到 Cloudflare token。
# 最後登出 wrangler：這台電腦從此對 Cloudflare 只能讀，其他專案也要各自設定 token。
# 隨時可以 Ctrl-C，之後重跑：已經寫好的值按 Enter 沿用。
# ──────────────────────────────────────────────────────────────────────────

source "$(dirname "${BASH_SOURCE[0]}")/wizard-helpers.sh"

ENV_FILE="$HOME/.config/naruhodo/cloudflare-readonly.env"
mkdir -p "$(dirname "$ENV_FILE")"

WORKER_NAME='naruhodo-api'
TOKEN_NAME='naruhodo-local-readonly'
OP_ITEM='naruhodo-cloudflare-readonly'
CF_API='https://api.cloudflare.com/client/v4'
CF_TOKEN=""   # 唯讀 token 本身：只在記憶體，不寫檔、不印出來

# json_get EXPR: 從 RESPONSE 取欄位，例如 json_get 'result.id'；取不到就是空字串。
json_get() {
  printf '%s' "$RESPONSE" | node -e '
    let s = ""; process.stdin.on("data", d => s += d).on("end", () => {
      let v; try { v = new Function("o", "return o." + process.argv[1])(JSON.parse(s)); } catch { v = undefined; }
      process.stdout.write(v == null ? "" : String(v));
    });' "$1"
}

# cf METHOD PATH [JSON]: 用 CF_TOKEN 呼叫 Cloudflare API（PATH 接在 /accounts/<id> 後面），設定 HTTP_STATUS 與 RESPONSE。
# 認證標頭寫進暫存檔再交給 curl，token 不會出現在 process list。
cf() {
  local method="$1" path="$2" body="${3:-}" out hdr
  out=$(mktemp); hdr=$(mktemp)
  printf 'Authorization: Bearer %s\nContent-Type: application/json\n' "$CF_TOKEN" > "$hdr"
  local args=(-sS -o "$out" -w '%{http_code}' -X "$method" -H "@$hdr")
  [[ -n "$body" ]] && args+=(--data "$body")
  HTTP_STATUS=$(curl "${args[@]}" "$CF_API/accounts/$CLOUDFLARE_ACCOUNT_ID$path") || HTTP_STATUS=000
  RESPONSE=$(cat "$out"); rm -f "$out" "$hdr"
}
cf_ok() { [[ "$HTTP_STATUS" =~ ^2 ]] && [[ "$(json_get 'success')" == true ]]; }
cf_errors() { json_get 'errors.map(e => e.code + " " + e.message).join("; ")'; }

# cf_upload_probe：上傳一個不相干的探測用 Worker（不碰 naruhodo-api），設定 HTTP_STATUS 與 RESPONSE。
# 唯讀 token 應該被拒絕；萬一成功，呼叫端會馬上刪掉它。
PROBE_WORKER='naruhodo-readonly-probe'
cf_upload_probe() {
  local out hdr dir
  out=$(mktemp); hdr=$(mktemp); dir=$(mktemp -d)
  printf 'Authorization: Bearer %s\n' "$CF_TOKEN" > "$hdr"
  printf 'export default { fetch() { return new Response("probe"); } };\n' > "$dir/probe.js"
  HTTP_STATUS=$(curl -sS -o "$out" -w '%{http_code}' -X PUT -H "@$hdr" \
    -F 'metadata={"main_module":"probe.js","compatibility_date":"2026-10-01"};type=application/json' \
    -F "probe.js=@$dir/probe.js;type=application/javascript+module" \
    "$CF_API/accounts/$CLOUDFLARE_ACCOUNT_ID/workers/scripts/$PROBE_WORKER") || HTTP_STATUS=000
  RESPONSE=$(cat "$out"); rm -rf "$out" "$hdr" "$dir"
}

# logged_in_to_wrangler：wrangler login 留下的 OAuth 登入還在。先把輸出存起來再比對：
# 直接 `whoami | grep -q` 的話，pipefail 會把 whoami 的非零 exit code 或 SIGPIPE 當成「沒比對到」。
logged_in_to_wrangler() {
  local output
  output=$(wrangler_unauthed whoami 2>&1 || true)
  [[ "$output" != *"not authenticated"* ]]
}

# wrangler_unauthed ARGS…：不帶任何 token 跑 wrangler，看的是 wrangler login 留下的 OAuth 登入。
wrangler_unauthed() { env -u CLOUDFLARE_API_TOKEN -u CLOUDFLARE_ACCOUNT_ID -u CLOUDFLARE_API_KEY npx --no-install wrangler "$@"; }

run_wizard() {

TOTAL_STAGES=7

cd "$(git rev-parse --show-toplevel)"
for tool in curl node op; do
  command -v "$tool" >/dev/null 2>&1 || { warn "需要 $tool，請先安裝"; exit 1; }
done
[[ -x node_modules/.bin/wrangler ]] || { warn "repo 裡還沒裝套件，先跑 npm ci"; exit 1; }
D1_DATABASE_ID=$(production_database_id)
[[ -n "$D1_DATABASE_ID" ]] || { warn "worker/wrangler.jsonc 沒有正式的 D1 database_id"; exit 1; }

banner "本機唯讀 Cloudflare token（ADR 0011）"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Cloudflare Account ID"
say "token 要建在擁有 naruhodo.page 的那個 Cloudflare 帳號底下。"
if [[ -z "$(_existing CLOUDFLARE_ACCOUNT_ID || true)" ]]; then
  PRODUCTION_ENV="$HOME/.config/naruhodo/production.env"
  if [[ -f "$PRODUCTION_ENV" ]]; then
    from_production=$(grep -E '^CLOUDFLARE_ACCOUNT_ID=' "$PRODUCTION_ENV" | tail -n1 | cut -d= -f2- | tr -d "'\"" || true)
    [[ -n "$from_production" ]] && write_env CLOUDFLARE_ACCOUNT_ID "$from_production" && note "沿用 production wizard 存的 Account ID。"
  fi
fi
if [[ -z "$(_existing CLOUDFLARE_ACCOUNT_ID || true)" ]]; then
  open_url "https://dash.cloudflare.com/"
  step "Cloudflare 後台按 Ctrl+K，搜尋「Copy account ID」並選擇（或 Workers & Pages → Account Details）。"
fi
while :; do
  ask CLOUDFLARE_ACCOUNT_ID "Account ID："
  [[ "$CLOUDFLARE_ACCOUNT_ID" =~ ^[0-9a-f]{32}$ ]] && break
  warn "Account ID 是 32 個十六進位字元，請再貼一次"
done
write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "建立唯讀 token"
say "這把 token 只能讀：查 D1、查歷史 log、即時 tail。沒有任何 Edit 權限，外洩也改不了程式碼、資料或 secrets。"
if [[ "$(_existing CLOUDFLARE_API_TOKEN || true)" == op://* ]] && ! confirm "已經設定過 1Password 參照，要換一把新的 token 嗎？"; then
  note "沿用現有的 token；第 4 步會從 1Password 取一次來驗證。"
else
  open_url "https://dash.cloudflare.com/?to=/:account/api-tokens"
  step "Account API tokens → Create Token → 最下面的 Custom token → Get started。"
  step "Token name 填 $TOKEN_NAME。"
  step "Permissions 加三列，全部選 Read："
  note "    D1 → Read"
  note "    Workers Tail → Read"
  note "    Workers Observability → Read"
  note "    （畫面上的名稱可能略有不同：選最接近的唯讀項。不要加任何 Edit。）"
  step "Client IP address filtering 留空；TTL 選一年。"
  step "Continue to summary → 確認只有上面三個 Read → Create Token → 複製 token（只會顯示一次）。"
  while :; do
    ask_secret CF_TOKEN "貼上 token（輸入不會顯示）："
    cf GET /tokens/verify
    [[ "$(json_get 'result.status')" == active ]] && break
    warn "Cloudflare 驗證不過（HTTP $HTTP_STATUS $(cf_errors)）：確認是 Account API token、而且複製完整"
  done
  note "✓ token 有效"
fi
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "存進 1Password"
if [[ -z "$CF_TOKEN" ]]; then
  note "沿用 1Password 裡現有的 token，略過。"
else
  say "token 只放在 1Password；設定檔只存指向它的 op:// 參照（不是 token 本身）。"
  step "打開 1Password → 新增項目 → API Credential（API 憑證）。"
  step "標題填 $OP_ITEM，credential 欄位貼上剛剛的 token（還在剪貼簿裡）→ 儲存。"
  step "在 credential 欄位旁按 ⋯ → Copy Secret Reference（複製密鑰參照）。"
  while :; do
    ask OP_REF "貼上參照（op://…）："
    [[ "$OP_REF" == op://* ]] && break
    warn "參照的開頭是 op://，請再複製一次"
  done
  write_env CLOUDFLARE_API_TOKEN "$OP_REF"
  copy_to_clipboard "" 2>/dev/null && note "已清空剪貼簿。"
fi
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "從 1Password 取一次（自動）"
say "用 op run 讀 $ENV_FILE，跟 npm run prod:connect 走同一條路：1Password 會跳一次授權，請允許。"
from_op=$(op run --env-file "$ENV_FILE" --no-masking -- node -e 'process.stdout.write(process.env.CLOUDFLARE_API_TOKEN ?? "")') || from_op=""
if [[ -z "$from_op" || "$from_op" == *op://* ]]; then
  warn "op run 沒有解出 token：確認 1Password 已解鎖、授權有按允許，參照也對（$ENV_FILE）；之後重跑"
  exit 1
fi
if [[ -n "$CF_TOKEN" && "$from_op" != "$CF_TOKEN" ]]; then
  warn "1Password 裡的值跟剛剛貼的 token 不一樣：確認存對欄位、複製的是這個欄位的參照，再重跑"
  exit 1
fi
CF_TOKEN="$from_op"; unset from_op
cf GET /tokens/verify
[[ "$(json_get 'result.status')" == active ]] || { warn "1Password 裡的 token 驗證不過（HTTP $HTTP_STATUS $(cf_errors)）"; exit 1; }
note "✓ op run 拿得到 token，而且有效"
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "實測：能讀、不能寫（自動）"
say "1. 對 production D1 跑 SELECT 1。"
cf POST "/d1/database/$D1_DATABASE_ID/query" '{"sql":"SELECT 1 AS ok"}'
if cf_ok; then
  note "✓ 讀得到"
else
  warn "SELECT 失敗（HTTP $HTTP_STATUS $(cf_errors)）：回第 2 步確認 token 有 D1 → Read"
  exit 1
fi
say "接下來兩個寫入一定要被拒絕，這是整個設定的重點，所以不能跳過。token 設對的話不會有任何改動；"
say "萬一成功了，wizard 會馬上刪掉建出來的東西，然後停下來。"
say "2. 對 D1 送一個真的會改資料的語句（建一張表）。"
cf POST "/d1/database/$D1_DATABASE_ID/query" '{"sql":"CREATE TABLE _readonly_probe (x INTEGER)"}'
if cf_ok; then
  cf POST "/d1/database/$D1_DATABASE_ID/query" '{"sql":"DROP TABLE _readonly_probe"}'
  warn "這把 token 能寫入 D1！已經刪掉測試表。到後台把這把 token 的 D1 改成 Read（或刪掉重建），再重跑"
  exit 1
fi
note "✓ D1 寫入被拒絕（HTTP $HTTP_STATUS $(cf_errors)）"
say "3. 上傳一個不相干的探測用 Worker $PROBE_WORKER（不碰 $WORKER_NAME），測部署權限。"
cf_upload_probe
if [[ "$HTTP_STATUS" =~ ^2 ]]; then
  cf DELETE "/workers/scripts/$PROBE_WORKER"
  warn "這把 token 能部署 Worker！已經刪掉 $PROBE_WORKER。到後台拿掉這把 token 的 Workers Scripts 權限（或刪掉重建），再重跑"
  exit 1
fi
note "✓ 部署被拒絕（HTTP $HTTP_STATUS $(cf_errors)）"
note "Worker secrets 的寫入跟部署是同一個權限（Workers Scripts Edit），所以也一併確認了。"
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "實測：log（自動）"
say "1. 查 $WORKER_NAME 最近一小時的 Workers Logs（npm run prod:logs 用的 API）。"
while :; do
  # 跟 prod:logs 用同一個 body（scripts/prod-access.ts 的 logsQueryBody）
  query=$(node --input-type=module -e '
    import { logsQueryBody } from "./scripts/prod-access.ts";
    process.stdout.write(JSON.stringify(logsQueryBody({ sinceMs: 3_600_000, limit: 1 }, Date.now())));')
  cf POST /workers/observability/telemetry/query "$query"
  if [[ "$HTTP_STATUS" =~ ^2 ]]; then
    note "✓ 查得到（Worker 開了 observability 之後才會有 log；現在可能還是空的）"
    break
  fi
  if [[ "$HTTP_STATUS" == 401 || "$HTTP_STATUS" == 403 ]]; then
    warn "沒有權限（HTTP $HTTP_STATUS $(cf_errors)）：這個 API 的文件只列了 Workers Observability 的 Edit。"
    note "ADR 0011 接受改成 Edit：它只能改 log 設定，碰不到程式碼、資料與 secrets，proxy 也只轉發查詢。"
    step "後台 Account API tokens → $TOKEN_NAME 的 ⋯ → Edit：Workers Observability 改成 Edit → Continue → Update token（token 值不變）。"
    confirm "改好了，要再試一次嗎？" && continue
    SKIPPED+=("歷史 log 查不了：npm run prod:logs 不能用，只剩 prod:tail")
    break
  fi
  warn "查詢失敗（HTTP $HTTP_STATUS $(cf_errors)）"
  SKIPPED+=("歷史 log 查詢失敗（HTTP $HTTP_STATUS）：observability 部署上去之後重跑第 6 步，還是失敗就請 Claude 看 scripts/prod-access.ts 的 logsQueryBody")
  break
done
say "2. 開一個 $WORKER_NAME 的 tail 再馬上關掉（npm run prod:tail 用的權限）。"
cf POST "/workers/scripts/$WORKER_NAME/tails" '{}'
if cf_ok; then
  tail_id=$(json_get 'result.id')
  cf DELETE "/workers/scripts/$WORKER_NAME/tails/$tail_id"
  note "✓ tail 開得起來"
else
  warn "開 tail 失敗（HTTP $HTTP_STATUS $(cf_errors)）"
  SKIPPED+=("tail 開不起來：確認 token 有 Workers Tail → Read")
fi
pause

# ── 7 ────────────────────────────────────────────────────────────────────
stage "登出 wrangler"
say "wrangler login 留下的 OAuth 登入有整個帳號的寫入權。登出後這台電腦對 Cloudflare 只能透過唯讀 token 讀。"
warn "整台電腦生效：其他專案如果也靠 wrangler login，之後要各自設定 token（可以照 docs/agents/prod-access.md 的做法）。"
if ! logged_in_to_wrangler; then
  note "wrangler 已經沒有登入。"
elif confirm "要登出 wrangler 嗎？（會向 Cloudflare 撤銷這組 OAuth 登入）"; then
  wrangler_unauthed logout || true
else
  SKIPPED+=("wrangler 還登入著：npx wrangler logout")
fi
leftover=()
for f in "$HOME/.wrangler/config/default.toml" \
         "${APPDATA:+$APPDATA/xdg.config/.wrangler/config/default.toml}" \
         "${XDG_CONFIG_HOME:-$HOME/.config}/.wrangler/config/default.toml" \
         "$HOME/Library/Preferences/.wrangler/config/default.toml"; do
  [[ -n "$f" && -f "$f" ]] && leftover+=("$f")
done
if (( ${#leftover[@]} )); then
  note "還有舊的 OAuth 登入檔（wrangler 換過設定路徑時留下的）："
  for f in "${leftover[@]}"; do note "    $f"; done
  if confirm "要刪掉這些檔案嗎？"; then
    rm -f "${leftover[@]}"
    note "✓ 已刪除"
  else
    SKIPPED+=("舊的 wrangler OAuth 登入檔還在：${leftover[*]}")
  fi
fi
if ! logged_in_to_wrangler; then
  note "✓ wrangler 沒有任何登入"
else
  warn "wrangler whoami 看起來還有登入"
  SKIPPED+=("wrangler 還有登入：npx wrangler whoami 看是哪一份設定，再 npx wrangler logout")
fi
CF_TOKEN=""
pause

finish
say "接下來查 production："
say "  • 在 Terminal 跑 npm run prod:connect（跳一次 1Password 授權），看到「連線中 →」"
say "  • 再用 npm run prod:sql -- \"SELECT …\"、npm run prod:logs、npm run prod:tail（docs/agents/prod-access.md）"
say "  • 歷史 log 要等開了 observability 的 Worker 部署上去（合併這次的 PR）才會開始累積。"
}

run_wizard "$@"; exit
